const fs=require('fs');
const p='public/index.html';
let s=fs.readFileSync(p,'utf8');
const marker='<!-- HOTBAR_EMPTY_ICON_FIX_V1 -->';
const css=`${marker}\n<style id="hotbar-empty-icon-fix-v1">\n.s.empty.has-icon .hotbar-icon{opacity:.22!important}\n.s.empty.has-icon:hover .hotbar-icon{opacity:.34!important}\n.s.has-icon:not(.empty) .hotbar-icon{opacity:1!important}\n</style>`;
s=s.replace(/<!-- HOTBAR_EMPTY_ICON_FIX_V1 -->[\s\S]*?<\/style>/,'');
if(!s.includes('</head>'))throw new Error('head end not found');
s=s.replace('</head>',css+'\n</head>');
fs.writeFileSync(p,s);
console.log('Hotbar empty custom icons made visible');
